import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    b = list(map(int, data[1:]))

    def can_restore(n, b):
        for a1 in range(1, 10**18 + 1):
            a = [a1]
            valid = True
            for i in range(n - 1):
                ai = a[-1]
                bi = b[i]
                if ai % b[(i + 1) % n] != bi:
                    valid = False
                    break
                a.append(ai // b[(i + 1) % n] * b[(i + 1) % n] + bi)
            if valid and a[-1] % a[0] == b[-1]:
                return True, a
        return False, []

    possible, a = can_restore(n, b)
    if possible:
        print("YES")
        print(" ".join(map(str, a)))
    else:
        print("NO")

if __name__ == "__main__":
    main()
